import json

# FT2 note numbers are 1-based: C-0=1, so midi+1
def N(midi): return midi + 1

S = "/workspace/work/samples/"
SAMPLES = [
    ("kick",  "kick.wav",  64, 128, 46),   # (name, file, volume, pan, rel_note)
    ("clap",  "clap.wav",  56, 132, 46),
    ("hatcl", "hatc.wav",  38, 112, 46),
    ("hatop", "hato.wav",  42, 144, 46),
    ("crash", "crash.wav", 48, 128, 46),
    ("bass",  "bass.wav",  52, 124, 46),
    ("lead",  "lead.wav",  54, 128, 58),
    ("arp",   "arp.wav",   46, 104, 70),
    ("pad",   "pad.wav",   40, 152, 58),
    ("riser", "riser.wav", 46, 128, 46),
]

calls = []
calls.append({"name":"module_new","arguments":{"channels":8,"name":"neon bypass"}})
for i,(nm,fn,vol,pan,rel) in enumerate(SAMPLES):
    instr = i+1
    calls.append({"name":"sample_load","arguments":{"path":S+fn,"instrument":instr,"sample":0}})
for i,(nm,fn,vol,pan,rel) in enumerate(SAMPLES):
    instr = i+1
    calls.append({"name":"sample_set","arguments":{"instrument":instr,"sample":0,"name":nm,
                   "volume":vol,"panning":pan,"finetune":0,"relative_note":rel,
                   "loop_start":0,"loop_length":0}})
    calls.append({"name":"instrument_set","arguments":{"instrument":instr,"name":nm}})

calls.append({"name":"song_set","arguments":{"name":"neon bypass","bpm":130,"speed":3,
             "length":12,"loop_start":0,"channels":8}})
for p in range(12):
    calls.append({"name":"order_set","arguments":{"position":p,"pattern":p}})
    calls.append({"name":"pattern_set_length","arguments":{"pattern":p,"rows":64}})

def cell(pattern, row, ch, note, instr, vol):
    return {"name":"pattern_set_cell",
            "arguments":{"pattern":pattern,"row":row,"channel":ch,
                         "note":N(note),"instrument":instr,"volume":vol}}

# ---------------- chord progressions (midi roots; q: 0=min,1=maj) ----------------
CH = [
    [(45,0),(41,1),(48,1),(43,1)],  # P0  Am F C G
    [(45,0),(41,1),(48,1),(40,1)],  # P1  Am F C E
    [(45,0),(41,1),(48,1),(43,1)],  # P2
    [(45,0),(41,1),(48,1),(43,1)],  # P3
    [(38,0),(46,1),(41,1),(43,1)],  # P4  Dm Bb F G
    [(38,0),(46,1),(40,1),(40,1)],  # P5  Dm Bb E E
    [(41,1),(43,1),(45,0),(45,0)],  # P6  F G Am Am
    [(41,1),(43,1),(40,1),(40,1)],  # P7  F G E E
    [(45,0),(41,1),(48,1),(43,1)],  # P8
    [(38,0),(46,1),(40,1),(43,1)],  # P9  Dm Bb E G
    [(45,0),(41,1),(48,1),(43,1)],  # P10
    [(41,1),(43,1),(40,1),(40,1)],  # P11 F G E E
]

for p, chords in enumerate(CH):
    # ---------- drums ----------
    if p == 0:
        for r in range(0,64,8):   calls.append(cell(p,r,0,45,1,40))   # kick 4floor
        for r in (8,24,40,56):    calls.append(cell(p,r,1,45,2,44))   # clap
        for r in range(0,64,2):   calls.append(cell(p,r,2,45,3,18))   # hat closed 16ths
        calls.append(cell(p,0,3,45,5,36))                              # crash on loop downbeat
        for r in (12,20,28,36,44,52,60): calls.append(cell(p,r,3,45,4,26))  # hat open
    elif p == 6:
        for r in (0,32):          calls.append(cell(p,r,0,45,1,40))
        for r in (16,48):         calls.append(cell(p,r,1,45,2,44))
        for r in range(0,64,4):   calls.append(cell(p,r,2,45,3,16))
    elif p == 7:
        for r in (0,32):          calls.append(cell(p,r,0,45,1,40))
        for r in (48,52,56,60):   calls.append(cell(p,r,0,45,1,38))
        for r in (16,48):         calls.append(cell(p,r,1,45,2,44))
        for r,v in zip((56,58,60,62),(28,32,36,40)): calls.append(cell(p,r,1,45,2,v))
        for r in range(32,64,2):  calls.append(cell(p,r,2,45,3,18))
        for r in (36,44,52,60):   calls.append(cell(p,r,3,45,4,26))
        calls.append(cell(p,0,3,45,10,44))                              # riser
    elif p == 11:
        for r in range(0,48,8):   calls.append(cell(p,r,0,45,1,40))
        for r in range(52,64,2):  calls.append(cell(p,r,0,45,1,38))     # kick roll
        for r in (8,24,40,56):    calls.append(cell(p,r,1,45,2,44))
        for r in range(0,64,2):   calls.append(cell(p,r,2,45,3,18))
        for r in (4,12,20,28,36,44,52,60): calls.append(cell(p,r,3,45,4,26))
    else:
        for r in range(0,64,8):   calls.append(cell(p,r,0,45,1,40))
        for r in (8,24,40,56):    calls.append(cell(p,r,1,45,2,44))
        for r in range(0,64,2):   calls.append(cell(p,r,2,45,3,18))
        for r in (4,12,20,28,36,44,52,60): calls.append(cell(p,r,3,45,4,26))

    # ---------- bass ----------
    roots = [c[0] for c in chords]
    if p == 6:
        for r,rt in zip((0,16,32,48),roots): calls.append(cell(p,r,4,rt,6,34))
        calls.append(cell(p,40,4,52,6,30))
    elif p == 7:
        for r in range(0,56,4):   calls.append(cell(p,r,4,40,6,40))
        for r in (14,30,46,54,62):calls.append(cell(p,r,4,52,6,34))
    elif p == 11:
        for cidx in range(4):
            rt = roots[cidx]; b = cidx*16
            for r in (0,4,8,12): calls.append(cell(p,b+r,4,rt,6,40))
            calls.append(cell(p,b+14,4,rt+12,6,36))
        for r,v in zip((56,58,60,62),(40,44,47,52)): calls.append(cell(p,r,4,v,6,36))
    elif p == 10:
        for cidx in range(4):
            rt = roots[cidx]; b = cidx*16
            for r in (0,4,8,12): calls.append(cell(p,b+r,4,rt,6,36))
            calls.append(cell(p,b+14,4,rt+12,6,32))
    else:
        for cidx in range(4):
            rt = roots[cidx]; b = cidx*16
            for r in (0,4,8,12): calls.append(cell(p,b+r,4,rt,6,40))
            calls.append(cell(p,b+14,4,rt+12,6,36))

    # ---------- arp ----------
    if p == 6:
        for cidx,(rt,q) in enumerate(chords):
            b = cidx*16
            cyc = [0,3,7,12] if q==0 else [0,4,7,12]
            for i,r in enumerate((0,4,8,12)):
                calls.append(cell(p,b+r,5,rt+12+cyc[i],8,34))
    elif p == 7:
        for cidx,(rt,q) in enumerate(chords[:2]):
            b = cidx*16
            cyc = [0,4,7,12]
            for i,r in enumerate((0,4,8,12)):
                calls.append(cell(p,b+r,5,rt+12+cyc[i],8,34))
        rt,q = chords[2]
        for cidx in (2,3):
            b = cidx*16
            cyc = [0,4,7,12,7,4,7,12]
            for i in range(8):
                calls.append(cell(p,b+2*i,5,rt+12+cyc[i],8,38 if i==0 else 30))
    elif p == 10:
        for cidx,(rt,q) in enumerate(chords):
            b = cidx*16
            cyc = [0,3,7,12] if q==0 else [0,4,7,12]
            for i,r in enumerate((0,4,8,12)):
                calls.append(cell(p,b+r,5,rt+12+cyc[i],8,32))
    else:
        for cidx,(rt,q) in enumerate(chords):
            b = cidx*16
            cyc = [0,3,7,12,7,3,7,12] if q==0 else [0,4,7,12,7,4,7,12]
            for i in range(8):
                calls.append(cell(p,b+2*i,5,rt+12+cyc[i],8,38 if i==0 else 30))

    # ---------- pad (power chord sample, root per chord) ----------
    pv = 26 if p in (6,7) else 28
    for cidx,(rt,q) in enumerate(chords):
        calls.append(cell(p,cidx*16,7,rt+12,9,pv))

# ---------------- lead ----------------
LEAD = {  # pattern -> (row, midi, vol)
 1: [(48,71,36),(52,86,36),(56,88,36)],
 2: [(0,57,40),(2,60,38),(4,64,40),(8,65,40),(10,69,38),(12,72,40),
     (16,67,40),(20,64,40),(24,62,40),(28,59,40)],
 3: [(0,64,40),(4,62,40),(8,60,40),(12,57,40),(16,60,40),(20,62,40),(24,64,40),(28,67,40)],
