 6: [(0,60,34),(16,62,34),(32,64,34),(48,60,34)],
 7: [(0,60,38),(2,62,36),(4,64,36),(6,65,36),(8,67,38),
     (16,59,38),(18,62,36),(20,67,36),(22,71,36),
     (32,76,40),(34,80,38),(36,83,38),(38,88,36),(40,88,36),
     (48,76,40),(52,80,40),(56,83,40),(60,88,36)],
 8: [(0,57,40),(2,60,38),(4,64,40),(8,65,40),(10,69,38),(12,72,40),
     (16,67,40),(20,64,40),(24,62,40),(28,59,40)],
 9: [(0,65,40),(4,69,40),(8,62,40),(12,65,40),
     (16,62,40),(20,65,40),(24,67,40),(28,69,40),
     (32,68,40),(36,71,40),(40,64,40),(44,68,40),
     (48,62,40),(52,59,40),(56,55,40),(60,62,40)],
 10:[(0,60,34),(8,57,34),(16,67,34),(24,64,34),(32,60,34),(40,57,34),(48,59,34)],
}
for p, notes in LEAD.items():
